pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), address(this)); }
    function testFuzz_property(bytes4 interfaceId) public {
        bool is1155 = interfaceId == type(IERC1155).interfaceId;
        bool isMetadata = interfaceId == type(IERC1155MetadataURI).interfaceId;
        bool is165 = interfaceId == type(IERC165).interfaceId;
        vm.assume(!is1155 && !isMetadata && !is165);
        bool referenceSupports = c.supportsInterface(interfaceId);
        assertTrue(!referenceSupports);
    }
}

interface IERC1155 {
    function safeTransferFrom(address, address, uint256, uint256, bytes calldata) external;
    function safeBatchTransferFrom(address, address, uint256[] calldata, uint256[] calldata, bytes calldata) external;
    function balanceOf(address, uint256) external view returns (uint256);
    function balanceOfBatch(address[] calldata, uint256[] calldata) external view returns (uint256[] memory);
    function setApprovalForAll(address, bool) external;
    function isApprovedForAll(address, address) external view returns (bool);
}

interface IERC1155MetadataURI is IERC1155 {
    function uri(uint256) external view returns (string memory);
}

interface IERC165 {
    function supportsInterface(bytes4 interfaceId) external view returns (bool);
}

