pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), address(this)); }
    function testFuzz_property(address account, uint256 id, uint256 mintAmount) public {
        // The bug is about calling balanceOf with the zero address.
        // In the reference, this call reverts, so we assert that any call with account == address(0) MUST revert.
        // In the buggy version, it will NOT revert (returns a value, possibly non-zero).
        // We do not restrict account: the fuzzer will explore all values, including address(0).
        // No adversarial helper is needed; the difference is directly observable via balanceOf.

        // Ensure we have a token to query (id must be under _itemCount).
        // We need to create at least one game item so that the id being queried exists.
        // We do this inside the test to keep it independent of fuzzed id.
        // However, vm.assume limits the id to a reasonable range to avoid massive loops.
        vm.assume(id < 10000);

        // Create some items if needed, but not per-fuzz call to avoid state explosion.
        // Instead, we let the fuzzer pick an id that might not exist; for non-existent ids, balanceOf returns 0 in both.
        // To guarantee a potential difference, we need the id to be valid.
        if (c.uniqueTokensOutstanding() == 0) {
            // create a single item with id 0
            vm.startPrank(address(this));
            c.adjustAdminAccess(address(this), true);
            c.createGameItem("test", "uri", false, false, 0, 0, 0);
            vm.stopPrank();
        }

        // Now, the fuzzer can give us any account, any id.
        // We want to assert that if account == address(0), the call reverts.
        // We wrap the call in try/catch and check revert status.
        bool reverted = false;
        try c.balanceOf(account, id) returns (uint256) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // The property: if account is address(0), the call MUST revert.
        if (account == address(0)) {
            assertTrue(reverted, "Reference: balanceOf for address(0) should revert");
        }
    }
}

